refs=[candidate_path,register_path,gold_path,'AGENTS.md','docs/board.json',BASE+'M03/planning/current-state.json',BASE+'M03/planning/preview-media-review-20261103/results.json',BASE+'M01/planning/exact-disposition-correction-review-20261103/results.json',BASE+'M02/planning/golden14-lock-review-20261103/results.json',BASE+'M01/planning/s2-green/source-current.json']
yellow=[]
for card in register['cards']:
    if card['light']!='Yellow': continue
    task_path=BASE+('IO-PREREQ/implementation/module-spec.json' if card['id']=='PD-P1-IO-PREREQ-IMPL-01' else card['id']+'.json'); task=read(task_path); refs.append(task_path)
