(OUT/'index.html').write_text('<!doctype html><meta charset="utf-8"><title>M03 Fixture provenance preparation</title><style>body{font:16px system-ui;max-width:1150px;margin:40px auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}details{border:1px solid #aaa;padding:16px;margin:12px}</style><h1>M03 fixture / provenance preparation</h1><p>DOCUMENT candidate delivered; independent review pending. Owner format / SDK / thresholds OPEN. Native decoder / renderer / product / build NOT RUN. Historical PASS suites NOT RERUN.</p>'+''.join('<details open><summary>'+html.escape(k)+'</summary><pre>'+html.escape(json.dumps(v,ensure_ascii=False,indent=2))+'</pre></details>' for k,v in payload.items())+'<script type="application/json" id="module-spec">'+json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')+'</script>',encoding='utf-8')
